from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).resolve().parent
folders={'en':'manuscript','es':'manuscript_es'}
base={k:(HERE/'baseline'/v/'main.tex').read_text().split('\n\n') for k,v in folders.items()}
blocks={k:v.copy() for k,v in base.items()};changes=[]
def r(i,note,en,es):
 for lang,body in [('en',en),('es',es)]:
  lines=base[lang][i].splitlines();pre=[];post=[]
  while lines and re.match(r'\\(?:section|subsection|clearpage|Needspace|FloatBarrier)',lines[0]):pre.append(lines.pop(0))
  for j,l in enumerate(lines):
   if l.startswith(('\\PanelFigure','\\input')):post=lines[j:];break
  blocks[lang][i]='\n'.join(pre+[body.strip()]+post)
 changes.append({'block':i,'reason':note})
def fig(i,en,es):
 for lang,caption in [('en',en),('es',es)]:
  s=blocks[lang][i];start=s.index('\\PanelFigure');tail=s[start:]
  m=re.fullmatch(r'\\PanelFigure\{([^}]+)\}\{.*\}\{([^}]+)\}\{([^}]+)\}',tail,re.S);assert m,tail
  blocks[lang][i]=s[:start]+'\\PanelFigure{'+m[1]+'}{'+caption.strip()+'}{'+m[2]+'}{'+m[3]+'}'
abstracts={
'en':r'''Science maps describe relationships between papers. Text embedding models build these relationships by turning a paper's text into a list of numbers that gives it a position. Would another model give the same picture? I compare ten models using titles and abstracts of 500,000 publications from the OpenAlex bibliographic catalogue, published in 2000--2024 across 26 disciplines, including Medicine and Physics. Representing each discipline by its papers' average position produces similar arrangements across models, including when other papers are selected. Yet within a discipline and period, two models share, on average, only eight of the 25 papers closest to a given paper. Supplying titles alone also changes much of that list, with effects that vary between models. Models can also disagree about which discipline's papers are more spread out. When spread is measured through angles from a common reference point, moving that point can change the comparison even when selecting other papers does not. These checks distinguish agreement between models from stability to article selection. The broad arrangement can remain similar while answers about nearby papers and differences between disciplines depend on the model, the text it receives and how its output is processed.''',
'es':r'''Los mapas de la ciencia describen relaciones entre artículos. Los modelos de embeddings de texto construyen esas relaciones al convertir el texto de un artículo en una lista de números que le da una posición. ¿Otro modelo daría la misma imagen? Comparo diez modelos con los títulos y resúmenes de 500.000 publicaciones de 2000--2024 del catálogo bibliográfico OpenAlex, repartidas en 26 disciplinas, como Medicina o Física. Representar cada disciplina mediante la posición media de sus artículos produce una organización parecida entre modelos, también al elegir otros artículos. Sin embargo, dentro de una disciplina y período, dos modelos comparten, en promedio, solo ocho de los 25 artículos más cercanos a un mismo trabajo. Darles solo los títulos también cambia buena parte de esa lista, con efectos que varían entre modelos. Los modelos también pueden discrepar sobre qué disciplina tiene sus artículos más dispersos. Cuando medimos esa dispersión mediante ángulos desde un punto común, mover ese punto puede cambiar la comparación, incluso cuando elegir otros artículos no la cambia. Estas pruebas distinguen el acuerdo entre modelos de la estabilidad al elegir artículos. La organización general puede mantenerse mientras las respuestas sobre artículos cercanos y diferencias entre disciplinas dependen del modelo, del texto que recibe y de cómo se procesa su salida.'''}
for lang,s in abstracts.items():
 old=blocks[lang][1];a=old.index('\n')+1;b=old.index('\\end{abstract}')
 blocks[lang][1]=old[:a]+s+'\n'+old[b:]
changes.append({'block':1,'reason':'Identificar el texto representado y distinguir acuerdo, selección y procesamiento sin exigir contexto previo.'})
r(2,'Explicar qué hace el modelo antes de hablar de cambiar la representación.',r'''A science map can help a reader find related papers or compare research areas. Its usefulness depends on the relationships it shows. When a model determines those relationships from text, choosing the model becomes part of choosing the map. Two models may lead a reader to different papers near the same starting article, or disagree about how widely an area's papers are spread. I ask how much the answer changes when we keep the papers and use another model to represent them.''',r'''Un mapa de la ciencia puede ayudar a encontrar artículos relacionados o a comparar áreas de investigación. Su utilidad depende de las relaciones que muestra. Cuando un modelo obtiene esas relaciones a partir del texto, elegir el modelo también forma parte de elegir el mapa. Dos modelos pueden llevar al lector a artículos distintos cerca de un mismo trabajo, o discrepar sobre lo dispersos que están los artículos de un área. En este estudio pregunto cuánto cambia la respuesta si mantenemos los artículos y usamos otro modelo para representarlos.''')
r(3,'Introducir vector, texto concreto y distancia sin presuponer lectura del artículo completo.',r'''The models studied here read a paper's title and abstract and turn that text into a list of numbers, called a vector or \emph{embedding}. The numbers act as coordinates: together they give the paper a position from which distances to other papers can be calculated. Papers placed close together are treated as related. This approach has been used to map biomedical literature and the structure of physics \citep{refbe130e2973,refc0e2cc29e0}. But the position comes from the model. It is not a relationship observed independently of it, and the title and abstract do not contain everything in the paper.''',r'''Los modelos de este estudio leen el título y el resumen de un artículo y convierten ese texto en una lista de números, llamada vector o \emph{embedding}. Los números funcionan como coordenadas: juntos dan al artículo una posición desde la que podemos calcular distancias a otros artículos. Los que quedan cerca se consideran relacionados. Este procedimiento se ha usado para cartografiar la literatura biomédica y la estructura de la física \citep{refbe130e2973,refc0e2cc29e0}. Pero la posición la produce el modelo. No es una relación observada con independencia de él, y el título y el resumen no contienen todo lo que dice el artículo.''')
r(5,'Dar una razón para cada paso y separar las tres preguntas.',r'''I use ten models and a fixed collection of 500,000 publications to examine three questions. The first concerns shared relationships: do models preserve the broad arrangement of areas and identify the same nearby papers? The second asks how much of a change comes from what the model reads: does supplying only a title matter as much as switching models? The third, added as a later exploration, concerns a description we might draw from the map: do models agree that one area's papers are more spread out than another's? Repeating each type of comparison with other selected articles also shows whether its answer depends on the particular papers used.''',r'''Utilizo diez modelos y una colección fija de 500.000 publicaciones para examinar tres preguntas. La primera trata sobre las relaciones compartidas: ¿conservan los modelos la organización general de las áreas y encuentran los mismos artículos cercanos? La segunda pregunta cuánto del cambio viene de lo que lee el modelo: ¿importa dar solo el título tanto como cambiar de modelo? La tercera, añadida como una exploración posterior, trata sobre una descripción que podríamos extraer del mapa: ¿coinciden los modelos en que los artículos de un área están más dispersos que los de otra? Repetir cada tipo de comparación con otras selecciones de artículos permite ver también si la respuesta depende de los trabajos concretos elegidos.''')
r(7,'Aclarar que entrada es lo que se entrega al modelo.',r'''The model is only one choice involved. The \emph{input text} is the text we give it to read: a title alone conveys less information than a title followed by its abstract. Models also accept different lengths of text and use different rules to produce a single vector for it. \citet{singh-singh-2022-inefficiency} show that scholarly search can be sensitive to the wording of short queries. The supplied text therefore belongs in the comparison alongside the model.''',r'''Elegir el modelo es solo una de las decisiones. El \emph{texto de entrada} es el que le damos para que lo lea: un título solo ofrece menos información que un título seguido de su resumen. Los modelos también admiten textos de distinta longitud y utilizan reglas distintas para producir un único vector. \citet{singh-singh-2022-inefficiency} muestran que la búsqueda académica puede ser sensible a cómo se redactan las consultas cortas. Por eso, el texto entregado al modelo forma parte de la comparación junto con el propio modelo.''')
r(9,'Definir selección, acuerdo y estabilidad por lo que permanece fijo.',r'''Two changes need to be kept separate. To measure \emph{agreement}, I keep the articles fixed and compare models. To check \emph{selection stability}, I keep the model fixed and choose other articles under the same rules. An \emph{article selection} is simply a set chosen from the existing collection; repeating it does not mean downloading new papers. A result can repeat with other articles in each model while the models consistently give opposite answers.''',r'''Conviene separar dos cambios. Para medir el \emph{acuerdo}, mantengo los artículos y comparo modelos. Para comprobar la \emph{estabilidad ante la selección}, mantengo el modelo y elijo otros artículos con las mismas reglas. Una \emph{selección de artículos} es un conjunto elegido de la colección existente; repetirla no significa descargar trabajos nuevos. Un resultado puede repetirse con otros artículos en cada modelo y, aun así, los modelos pueden dar siempre respuestas opuestas.''')
r(11,'Separar relaciones entre objetos, dispersión interna y dibujo bidimensional.',r'''The word map needs one further distinction here. I compare the numerical positions, each with hundreds of coordinates, before reducing them to a drawing. A two-dimensional plot would add a transformation that could change apparent distances. \emph{Structure} means the pattern of relationships among the objects being compared, whether papers or area summaries. \emph{Spread} describes how far apart the representations lie within one area. Two models can share much of the broad structure without agreeing on every area's spread.''',r'''La palabra mapa necesita otra precisión. Comparo las posiciones numéricas, cada una con cientos de coordenadas, antes de reducirlas a un dibujo. Un gráfico de dos dimensiones añadiría una transformación que podría cambiar las distancias aparentes. Llamo \emph{estructura} al patrón de relaciones entre los objetos que comparamos, sean artículos o resúmenes de áreas. La \emph{dispersión} describe cuánto se separan las representaciones dentro de un área. Dos modelos pueden compartir buena parte de la estructura general sin coincidir sobre la dispersión de cada área.''')
r(14,'Hacer comprensible la segunda propiedad antes de su definición técnica.',r'''\textbf{RQ3.} Do models agree about which area's paper representations are more spread out, or whether that spread is concentrated along a few directions rather than many? Do these comparisons repeat with other articles?''',r'''\textbf{PI3.} ¿Coinciden los modelos sobre qué área tiene sus representaciones más dispersas, o sobre si esa dispersión se concentra en pocas direcciones o se reparte entre muchas? ¿Se repiten estas comparaciones con otros artículos?''')
r(16,'Presentar OpenAlex, registro y corpus antes de las reglas de inclusión.',r'''OpenAlex is a bibliographic catalogue that supplies titles, abstracts and other information about publications \citep{priem2022openalex}. The starting collection, or corpus, contains 500,000 distinct work IDs retrieved and cleaned by 15 September 2026. Records were labelled as English articles, reviews or conference papers published in 2000--2024. Each required a title, an abstract of at least 50 words reconstructed from OpenAlex's stored format, and a primary research area. Retractions, ancillary material and clear content failures were excluded. Less certain cases and possible duplicate versions were retained with review flags. Those flags record a concern for later checks; they do not establish that every retained record is correct. Supplement S1 gives the rules and counts.''',r'''OpenAlex es un catálogo bibliográfico que proporciona títulos, resúmenes y otros datos de publicaciones \citep{priem2022openalex}. La colección de partida, o corpus, contiene 500.000 identificadores distintos de trabajos descargados y limpiados hasta el 15 de septiembre de 2026. Los registros estaban etiquetados como artículos, revisiones o trabajos de congreso en inglés, publicados entre 2000 y 2024. Cada uno debía tener título, un resumen de al menos 50 palabras reconstruido a partir del formato que guarda OpenAlex y un área principal. Se excluyeron retractaciones, material accesorio y fallos claros de contenido. Los casos menos seguros y las posibles versiones duplicadas se conservaron con marcas de revisión. Esas marcas registran una duda para las comprobaciones posteriores; no certifican que todos los registros conservados sean correctos. El Suplemento S1 recoge las reglas y los recuentos.''')
r(18,'Definir grupo área-período con ejemplo y finalidad del refuerzo.',r'''The collection has two parts. Reproducible random requests to OpenAlex supplied 400,000 eligible records. Another 100,000 were added to strengthen groups that initially had few papers from the same area and five-year period. For example, Medicine in 2000--04 is one such group. The five periods are 2000--04, 2005--09, 2010--14, 2015--19 and 2020--24. Combined with the 26 areas, they give 130 area--period groups, each with at least 2,165 papers. Searches across the whole general collection use the original 400,000 records; comparisons within areas can use both parts. The reinforcement makes smaller groups easier to compare, but changes their share of the collection. Neither that share nor an average giving every area equal weight estimates world publication proportions.''',r'''La colección tiene dos partes. Las peticiones aleatorias a OpenAlex, con las elecciones registradas para poder repetirlas, proporcionaron 400.000 registros que cumplían los requisitos. Otros 100.000 reforzaron los grupos que inicialmente tenían pocos artículos de una misma área y período de cinco años. Por ejemplo, Medicina en 2000--04 es uno de esos grupos. Los cinco períodos son 2000--04, 2005--09, 2010--14, 2015--19 y 2020--24. Al combinarlos con las 26 áreas obtenemos 130 grupos de área y período, cada uno con al menos 2.165 artículos. Las búsquedas en toda la colección general utilizan los 400.000 registros iniciales; las comparaciones dentro de áreas pueden usar ambas partes. El refuerzo facilita comparar los grupos pequeños, pero cambia su peso en la colección. Ni ese peso ni una media que da la misma importancia a cada área estiman las proporciones de la producción científica mundial.''')
r(19,'Identificar cada conjunto por su función y explicar reutilización.',r'''All ten models represent the 500,000 papers using titles and abstracts, but each subsequent question uses the articles it needs. The \emph{input-text experiment} compares titles, abstracts and both together on the same 52,000 papers: 2,000 per area, with 400 from each period. These include the 26,000 used in the first, smaller trial. The later study of spread within areas reuses this set and its title-plus-abstract vectors. The \emph{common-passage check} uses a different set of 52,000 papers to ensure that every model reads exactly the same passage, short enough to fit all input limits. This separates a choice about content from a choice about length. Table~\ref{tab:T01} is a guide to these comparisons; its rows overlap and should not be added together. Within any comparison, the models always represent the same paper IDs.''',r'''Los diez modelos representan los 500.000 artículos mediante sus títulos y resúmenes, pero cada pregunta posterior utiliza los artículos que necesita. El \emph{experimento de texto} compara títulos, resúmenes y ambos juntos en los mismos 52.000 artículos: 2.000 por área, con 400 de cada período. Incluyen los 26.000 de la primera prueba más pequeña. El estudio posterior de la dispersión dentro de las áreas reutiliza este conjunto y sus vectores de título más resumen. La \emph{comprobación de fragmento común} utiliza otro conjunto distinto de 52.000 artículos para que todos los modelos lean exactamente el mismo fragmento, suficientemente corto para caber en todos. Así se distingue una elección sobre el contenido de otra sobre su longitud. La Tabla~\ref{tab:T01} sirve de guía para estas comparaciones; sus filas se solapan y no deben sumarse. Dentro de cada comparación, los modelos siempre representan los mismos identificadores de artículos.''')
r(20,'Aclarar modelos ya entrenados y alcance de la selección.',r'''The ten models in Table~\ref{tab:T02} were already trained before this study. I use their published versions to convert text into vectors, without training them again on this collection. They cover scientific documents, general sentence similarity, and scientific or biomedical language. Their use in scholarly representation and their different training approaches motivated the selection. This is a fixed comparison set, not a random sample of models or a ranking of the newest systems. Versions, input formats and software settings were fixed before calculating the vectors.''',r'''Los diez modelos de la Tabla~\ref{tab:T02} ya estaban entrenados antes de este estudio. Utilizo sus versiones publicadas para convertir texto en vectores, sin volver a entrenarlos con esta colección. Abarcan documentos científicos, semejanza entre frases de uso general y lenguaje científico o biomédico. Se eligieron por su uso para representar literatura académica y por sus distintas formas de entrenamiento. Son un conjunto fijo de comparación, no una muestra aleatoria de modelos ni una clasificación de los sistemas más recientes. Las versiones, los formatos de entrada y la configuración de los programas se fijaron antes de calcular los vectores.''')
r(21,'Explicar recorte, tokens y por qué existe la prueba de fragmento común.',r'''The main input is the title followed by the abstract, in each model's usual format. Models divide text into small pieces called \emph{tokens}, which can be whole words or parts of words. A token limit is therefore not a word limit. Under their standard settings, MiniLM reads at most 256 tokens and MPNet 384; text beyond that limit is cut off. This affects 49.58\% and 20.16\% of the papers, respectively. I retain those settings and test MiniLM at 512 tokens separately. The common-passage check addresses the resulting difference in what models can read: all receive the same content, although each splits it into tokens in its own way.''',r'''La entrada principal es el título seguido del resumen, con el formato habitual de cada modelo. Los modelos dividen el texto en piezas pequeñas llamadas \emph{tokens}, que pueden ser palabras enteras o partes de palabras. Un límite de tokens no equivale, por tanto, a un límite de palabras. Con su configuración habitual, MiniLM lee como máximo 256 tokens y MPNet 384; el texto que sobrepasa ese límite se recorta. Esto afecta al 49,58\% y al 20,16\% de los artículos, respectivamente. Mantengo esas configuraciones y pruebo MiniLM con 512 tokens por separado. La comprobación de fragmento común aborda la diferencia en lo que pueden leer: todos reciben el mismo contenido, aunque cada modelo lo divida en tokens a su manera.''')
r(22,'Explicar pooling sin capas de jerga y mantener la receta exacta en tabla y suplemento.',r'''A further choice concerns how a model produces one vector for the whole paper. BERT, SciBERT, BioBERT and PubMedBERT produce an output vector at each token position, but were not trained specifically to compare whole documents. The main rule averages those outputs after the model has finished processing the text. This step is called \emph{mean pooling}. The average includes special symbols used to mark the text and excludes empty positions added as padding. Two alternatives take only the output at the first special-symbol position (CLS) or at the final non-padding position (SEP). These outputs have processed the surrounding text; they do not represent only the first or last word. The mean rule was specified before the primary comparisons and retained after early checks, rather than chosen to maximise agreement. The other six models use their documented rules. Table~\ref{tab:T02} and Supplement S1 specify the exact settings.
\input{tables/tex/T02}'''.replace('\n\\input{tables/tex/T02}',''),r'''Otra decisión es cómo obtiene el modelo un único vector para todo el artículo. BERT, SciBERT, BioBERT y PubMedBERT producen un vector de salida en cada posición de token, pero no se entrenaron específicamente para comparar documentos completos. La regla principal calcula la media de esas salidas una vez que el modelo ha terminado de procesar el texto. Este paso se llama \emph{pooling por media}. El promedio incluye los símbolos especiales que delimitan el texto y excluye las posiciones vacías añadidas como relleno. Dos alternativas toman solo la salida de la primera posición de símbolo especial (CLS) o la de la última posición sin relleno (SEP). Estas salidas han procesado el texto que las rodea; no representan solo la primera o la última palabra. La regla de la media se fijó antes de las comparaciones principales y se mantuvo tras las primeras comprobaciones, sin elegirla para maximizar el acuerdo. Los otros seis modelos utilizan sus reglas documentadas. La Tabla~\ref{tab:T02} y el Suplemento S1 precisan la configuración exacta.''')
r(23,'Usar una imagen sencilla para normalización y distinguir centro de artículos individuales.',r'''A vector can be pictured as an arrow from a common starting point to the paper's position. Before comparison, I scale every arrow to length one, keeping the direction in which it points. This operation is called \emph{normalisation}; it prevents differences in vector length from determining closeness. To summarise an area, I average its article vectors and also scale the resulting vector to length one. I call this summary its \emph{centre}. Comparing the centres asks whether models place areas in similar relationships to one another. Comparing the individual papers inside an area asks how much of its internal organisation they share.''',r'''Podemos imaginar un vector como una flecha que va desde un punto común hasta la posición del artículo. Antes de comparar, ajusto todas las flechas a longitud uno, conservando hacia dónde apuntan. Esta operación se llama \emph{normalización}; evita que las diferencias de longitud de los vectores determinen la cercanía. Para resumir un área, calculo la media de los vectores de sus artículos y ajusto también el resultado a longitud uno. Llamo \emph{centro} a ese resumen. Comparar los centros pregunta si los modelos sitúan las áreas en relaciones parecidas entre sí. Comparar los artículos individuales de un área pregunta cuánto comparten de su organización interna.''')
r(24,'Desarrollar las condiciones de centros y la función de los grupos aleatorios.',r'''The first centre comparison fixes 256 papers per group, so that unequal group sizes do not drive the comparison. It considers the 26 areas, the 217 specialties, and a restricted set containing one specialty from each area. To test dependence on which papers were chosen, I repeat article selection fifty times while keeping each group's counts from the five publication periods. To test dependence on size, I use 128, 256 and 512 papers for the same 26 areas and the 183 specialties that have enough papers at every size. These are comparison settings, not a claim that one size is universally sufficient.

Each selection also supplies a reference: the same papers are randomly redistributed into groups while preserving group sizes and publication-period counts. The reference asks how much model agreement remains when groups no longer follow the area or specialty labels. Further checks leave out one area at a time and, for the restricted specialty set, separate choosing a specialty from choosing its papers. Supplement S9 details these centre checks.''',r'''La primera comparación de centros fija 256 artículos por grupo, para que las diferencias de tamaño entre grupos no determinen la comparación. Considera las 26 áreas, las 217 especialidades y un conjunto reducido con una especialidad de cada área. Para comprobar cuánto importa qué artículos elegimos, repito la selección cincuenta veces, conservando los recuentos de los cinco períodos de publicación dentro de cada grupo. Para comprobar cuánto importa el tamaño, utilizo 128, 256 y 512 artículos en las mismas 26 áreas y las 183 especialidades que tienen suficientes trabajos en los tres tamaños. Son condiciones de comparación, no una afirmación de que un tamaño sea suficiente en cualquier estudio.

Cada selección aporta también una referencia: redistribuyo al azar los mismos artículos entre grupos, conservando el tamaño y los recuentos por período de cada grupo. Así podemos ver cuánto acuerdo queda entre modelos cuando los grupos dejan de seguir las etiquetas de área o especialidad. Otras pruebas retiran un área cada vez y, en el conjunto reducido de especialidades, separan la elección de una especialidad de la elección de sus artículos. El Suplemento S9 detalla estas comprobaciones de centros.''')
r(25,'Dar autonomía al método de vecinos y explicar por qué importa el conjunto candidato.',r'''\subsection{Finding and comparing nearby papers}
For an individual paper, its \emph{neighbours} are the papers placed closest to it. The \emph{starting paper} is the one whose neighbours we seek; the \emph{candidates} are all papers available for that search. Each model returns the closest 25, and agreement is the fraction that appears in both models' lists. Lists of 10 and 50 provide checks. Closeness uses cosine similarity: arrows pointing in more similar directions count as closer. The starting paper cannot be its own neighbour. The lists are calculated exactly and checked by independent sorting.

A search depends on the papers available to it. Searching among every paper from the same area and period gives different groups different numbers of candidates. A separate check fixes 2,048 candidates per group to remove that difference in count. Within a group, every model searches the same papers. A further search uses the 400,000 general records without area or period restrictions. These comparisons answer different questions, so each result specifies its candidate set.''',r'''\subsection{Cómo se buscan y comparan los artículos cercanos}
Los \emph{vecinos} de un artículo son los artículos que quedan más cerca de él. El \emph{artículo de partida} es aquel para el que buscamos vecinos; los \emph{candidatos} son todos los artículos entre los que podemos buscarlos. Cada modelo devuelve los 25 más cercanos, y el acuerdo es la fracción que aparece en las listas de ambos modelos. Las listas de 10 y 50 sirven de comprobación. La cercanía se mide con la similitud coseno: las flechas que apuntan en direcciones más parecidas cuentan como más cercanas. El artículo de partida no puede ser su propio vecino. Las listas se calculan de forma exacta y se comprueban mediante una ordenación independiente.

Una búsqueda depende de los artículos que tiene disponibles. Buscar entre todos los de una misma área y período ofrece cantidades distintas de candidatos según el grupo. Otra comprobación fija 2.048 candidatos por grupo para eliminar esa diferencia de cantidad. Dentro de un grupo, todos los modelos buscan entre los mismos artículos. Una búsqueda adicional utiliza los 400.000 registros generales, sin limitar área ni período. Estas comparaciones responden a preguntas distintas; por eso, cada resultado indica su conjunto de candidatos.''')
r(26,'Explicar qué se filtra y por qué se mantienen los artículos de partida.',r'''The quality check asks whether flagged records and duplicates explain disagreement between models. Applying the existing review flags and duplicate rule leaves 448,886 records. I compare neighbour lists for the same retained starting papers before and after filtering the candidates. Removing records also reduces search size, so further checks hold that size fixed: 1,024 candidates in all 130 groups, and 2,048 in the 63 groups still large enough after filtering. The before-and-after sets include the same 100 clean starting papers per group. Here, clean means passing the recorded filter; it does not mean that every possible source error has been ruled out.''',r'''La comprobación de calidad pregunta si los registros marcados y los duplicados explican el desacuerdo entre modelos. Aplicar las marcas de revisión y la regla de duplicados existentes deja 448.886 registros. Comparo las listas de vecinos de los mismos artículos de partida conservados antes y después de filtrar los candidatos. Quitar registros también reduce el tamaño de búsqueda; por eso, otras pruebas lo mantienen fijo: 1.024 candidatos en los 130 grupos y 2.048 en los 63 que siguen teniendo suficientes artículos tras el filtro. Los conjuntos de antes y después incluyen los mismos 100 artículos de partida limpios por grupo. Aquí, limpios significa que pasan el filtro registrado; no significa que se haya descartado todo posible error de origen.''')
r(27,'Conectar alcance de búsqueda con el control anterior y conservar el ejemplo concreto.',r'''To separate search scope from search size, I compare a specialty with its parent area using the same candidate count and matched dates. Consider 50 fixed starting papers from Cardiology and Cardiovascular Medicine. For each, we search among 256 cardiology papers and among 256 papers from Medicine. Both sets include those same 50 starting papers, leaving 206 places for others; the current starting paper is excluded when its neighbours are ranked. I choose the other 206 ten times, keeping the 50 fixed and matching publication-period counts between searches. The procedure covers 217 specialties, giving 10,850 starting papers. It deliberately includes the 50 specialty papers in the broader set too. Its result therefore applies to this matched comparison, rather than to an unrestricted random selection from Medicine.''',r'''Para separar el alcance de la búsqueda de su tamaño, comparo una especialidad con su área usando la misma cantidad de candidatos y fechas emparejadas. Pensemos en 50 artículos de partida fijos de Cardiología y Medicina Cardiovascular. Para cada uno, buscamos entre 256 artículos de esa especialidad y entre 256 de Medicina. Ambos conjuntos incluyen los mismos 50 artículos de partida; quedan 206 plazas para otros trabajos. Al ordenar los vecinos, se excluye el artículo para el que estamos buscando. Elijo los otros 206 diez veces, manteniendo fijos los 50 y el mismo reparto de períodos entre ambas búsquedas. El procedimiento abarca 217 especialidades: 10.850 artículos de partida en total. También incluye deliberadamente los 50 artículos de la especialidad en el conjunto amplio. Por tanto, el resultado corresponde a esta comparación emparejada, no a una selección aleatoria sin restricciones dentro de Medicina.''')
r(28,'Explicar qué compara CKA y cómo leer su valor sin identificar coordenadas de modelos distintos.',r'''To measure shared structure, I compare the pattern of relationships among the same objects under two models. The objects can be individual papers or the centres that summarise areas. The main measure is corrected linear centred kernel alignment, abbreviated CKA \citep{pmlr-v97-kornblith19a,refa961d84a4e}. It compares these patterns without requiring a coordinate in one model to mean the same thing as a coordinate in another. A value near one, such as 0.9, indicates that the patterns are very similar on this measure. It does not mean that a corresponding percentage of science is correctly represented. The correction reduces a known upward distortion associated with finite samples; it does not remove all statistical bias.

Two further measures check other aspects of shared structure. Procrustes alignment allows the representations to rotate and change scale before comparing them. The distance-rank check asks whether pairs of papers have a similar ordering from nearer to further apart. These measures need not give identical answers \citep{NEURIPS2021_252a3dba,pmlr-v285-williams24a}. Their formulas appear in Supplement S2.''',r'''Para medir la estructura compartida, comparo el patrón de relaciones entre los mismos objetos según dos modelos. Los objetos pueden ser artículos individuales o los centros que resumen áreas. La medida principal es la alineación lineal de núcleos centrados con corrección, abreviada CKA \citep{pmlr-v97-kornblith19a,refa961d84a4e}. Compara esos patrones sin exigir que una coordenada de un modelo signifique lo mismo que una coordenada de otro. Un valor cercano a uno, como 0,9, indica que los patrones se parecen mucho según esta medida. No significa que ese porcentaje de la ciencia esté representado correctamente. La corrección reduce una elevación artificial conocida de la puntuación cuando se usan muestras finitas; no elimina todo el sesgo estadístico.

Otras dos medidas comprueban aspectos distintos de la estructura compartida. La alineación de Procrustes permite girar y cambiar de escala las representaciones antes de compararlas. La comprobación del orden de distancias pregunta si las parejas de artículos siguen un orden parecido, desde las más cercanas hasta las más alejadas. Estas medidas no tienen por qué dar respuestas idénticas \citep{NEURIPS2021_252a3dba,pmlr-v285-williams24a}. Sus fórmulas aparecen en el Suplemento S2.''')
r(29,'Distinguir ángulos, ejes de variación y orden entre áreas.',r'''\subsection{Describing spread within an area}
A different question concerns the shape formed by the papers within each area. I describe two properties. \emph{Angular spread} summarises the angles between their vectors, using the median-distance convention in Supplement S6. Picture arrows drawn from a common point to the papers: larger angles mean that the arrows point further apart.

\emph{Effective linear dimension} describes how that cloud of paper positions spreads across directions. Here, variation means differences between the papers' coordinates. A cloud concentrated along a line varies mainly in one direction; one spread across a plane varies in more. The participation ratio, or PR, extends this idea to the full vector space and allows values between whole numbers. A larger PR means that variation is less concentrated in a few directions. Neither PR nor angular spread counts research topics or establishes thematic diversity.''',r'''\subsection{Cómo se describe la dispersión dentro de un área}
Otra pregunta distinta trata sobre la forma que dibujan los artículos dentro de cada área. Describo dos propiedades. La \emph{apertura angular} resume los ángulos entre sus vectores, con la regla de distancia mediana del Suplemento S6. Podemos imaginar flechas trazadas desde un punto común hasta los artículos: ángulos mayores indican que las flechas apuntan en direcciones más separadas.

La \emph{dimensión lineal efectiva} describe cómo se extiende esa nube de posiciones de artículos entre distintas direcciones. Aquí, variación significa diferencias entre las coordenadas de los artículos. Una nube concentrada a lo largo de una línea varía sobre todo en una dirección; otra extendida sobre un plano varía en más. La razón de participación, o PR, lleva esta idea al espacio completo de los vectores y admite valores entre números enteros. Un PR mayor indica que la variación está menos concentrada en unas pocas direcciones. Ni PR ni la apertura angular cuentan temas de investigación o establecen diversidad temática.''')
r(30,'Describir alternativas como comprobación de la fórmula y motivar conexión.',r'''Alternative angle summaries and dimension measures check how much the answer depends on the formula. For dimension, the entropy-based alternative measures how evenly variation is distributed. D80 counts the fewest directions needed to account for 80\% of that variation. Because these alternatives describe the same underlying variation, agreement among them would not independently validate a thematic interpretation. I also tested a further idea: whether weak links between nearby papers could reveal an area split into separate groups. Artificial examples exposed problems with reading that signal as thematic fragmentation. Supplement S6 gives the definitions and controls.''',r'''Otras formas de resumir los ángulos y medir la dimensión comprueban cuánto depende la respuesta de la fórmula. Para dimensión, la alternativa basada en entropía mide cómo se reparte la variación. D80 cuenta el menor número de direcciones necesarias para explicar el 80\% de esa variación. Como estas alternativas describen la misma variación de partida, que coincidan no validaría de forma independiente una interpretación temática. Probé también otra idea: si los enlaces débiles entre artículos cercanos podían revelar un área dividida en grupos separados. Los ejemplos artificiales mostraron problemas para leer esa señal como fragmentación temática. El Suplemento S6 recoge las definiciones y los controles.''')
r(31,'Definir orden persistente, sus 26 condiciones y centrado sobre los 52000 concretos.',r'''With 26 areas, there are 325 ways to choose two different areas, counting each pair once. For each property, each model gives a value for area A and a value for area B. I ask whether the same area keeps the larger value when different papers are chosen. The main calculation uses 2,000 papers per area. I repeat it with twenty half samples of 1,000 and five further selections of 2,000. An ordering is \emph{persistent} only if it holds in all 26 conditions. This refers to the order of the two measured values, not to the direction in which a vector points. The dimension alternatives use the same conditions.

Another check changes the common point from which the arrows are drawn. For each model, I calculate the mean of the balanced 52,000 unit vectors used in the input-text experiment, subtract it from every vector, and scale each resulting vector back to length one. This is \emph{global centring followed by normalisation}. The new origin is the average position in this set. I then recalculate spread and dimension to ask whether comparisons between areas depend on that choice. Supplement S6 distinguishes this change to the vectors from the internal centring already used in the PR formula.''',r'''Con 26 áreas hay 325 formas de elegir dos áreas distintas, contando cada pareja una sola vez. Para cada propiedad, cada modelo da un valor al área A y otro al área B. Pregunto si la misma área conserva el valor mayor cuando elegimos otros artículos. El cálculo principal utiliza 2.000 artículos por área. Lo repito con veinte medias muestras de 1.000 y cinco selecciones adicionales de 2.000. Un orden es \emph{persistente} solo si se mantiene en las 26 condiciones. Esto se refiere al orden de los dos valores medidos, no a la dirección en la que apunta un vector. Las alternativas de dimensión usan las mismas condiciones.

Otra comprobación cambia el punto común desde el que trazamos las flechas. Para cada modelo, calculo la media de los 52.000 vectores de longitud uno del experimento de texto, equilibrados por área y período, la resto a cada vector y vuelvo a ajustar su longitud a uno. Esta operación se llama \emph{centrado global seguido de normalización}. El nuevo origen es la posición media de este conjunto. Después vuelvo a calcular apertura y dimensión para ver si las comparaciones entre áreas dependen de esa elección. El Suplemento S6 distingue este cambio de los vectores del centrado interno que ya utiliza la fórmula de PR.''')
r(32,'Separar regla de clasificación, empates y mínimos relativos sin sobregeneralizar casos sin resolver.',r'''The results fall into three classes. In \emph{unanimous agreement}, all ten models persistently give the same area the larger value. In \emph{opposition}, at least two fixed models persistently give opposite orderings. Otherwise the comparison is \emph{unresolved}. For example, some models may change their ordering with other articles and no fixed pair may maintain opposite answers. Unresolved does not mean equal. Nor does a tie in one model necessarily leave the whole comparison unresolved: two other models can still maintain opposite orderings.

I also ask whether the differences are large enough to matter numerically. Besides any nonzero difference, I require minimum differences of 1, 5 and 10\% of the two areas' average value. A model's ordering counts at a given cutoff only if its difference exceeds that cutoff in every selection. The three classification rules are then applied again. These percentages describe the size of a measured difference, distinct from the percentage of the 325 pairs assigned to a class. They are sensitivity checks, not universal thresholds of scientific importance.''',r'''Los resultados se agrupan en tres clases. Hay \emph{acuerdo unánime} si los diez modelos dan de forma persistente el valor mayor a la misma área. Hay \emph{oposición} si al menos dos modelos concretos mantienen órdenes opuestos. En los demás casos, la comparación queda \emph{sin resolver}. Por ejemplo, algunos modelos pueden cambiar de orden con otros artículos y ninguna pareja fija mantener respuestas contrarias. Sin resolver no significa iguales. Tampoco un empate en un modelo deja necesariamente toda la comparación sin resolver: otros dos modelos pueden mantener órdenes opuestos.

También pregunto si las diferencias tienen suficiente tamaño numérico. Además de cualquier diferencia distinta de cero, exijo diferencias mínimas del 1, 5 y 10\% del valor medio de las dos áreas. El orden de un modelo solo cuenta con un corte determinado si su diferencia supera ese corte en todas las selecciones. Después se vuelven a aplicar las tres reglas de clasificación. Estos porcentajes describen el tamaño de una diferencia medida; son distintos del porcentaje de las 325 parejas que acaba en una clase. Son comprobaciones de sensibilidad, no umbrales universales de importancia científica.''')
r(33,'Distinguir alerta de clasificación y aclarar qué describen los rangos.',r'''A separate diagnostic, the \emph{selection alert}, marks a result that changes more than a recorded tolerance allows when we choose other articles or use another tested size. It identifies a result worth examining for sensitivity to article choice; it is neither a source-record error nor one of the three area-pair classes above. Each check has its own rule and count, retained in the supplement.

Selections overlap because they come from the same fixed collection. Their ranges describe changes among the available papers, rather than confidence intervals for all scientific literature. A central 95\% selection range leaves out the lowest 2.5\% and highest 2.5\% of the recorded results. Comparisons also reuse models and areas, so I describe their patterns without treating them as independent observations in significance tests.''',r'''Otro diagnóstico distinto, la \emph{alerta de selección}, señala un resultado que cambia más de lo permitido por una tolerancia registrada al elegir otros artículos o usar otro tamaño de los probados. Identifica un resultado cuya sensibilidad a la elección de artículos conviene examinar; no es un error en un registro ni una de las tres clases de parejas de áreas anteriores. Cada comprobación tiene su propia regla y recuento, conservados en el suplemento.

Las selecciones se solapan porque proceden de la misma colección fija. Sus rangos describen cambios entre los artículos disponibles, no intervalos de confianza para toda la literatura científica. Un rango central del 95\% de las selecciones deja fuera el 2,5\% inferior y el 2,5\% superior de los resultados registrados. Las comparaciones también reutilizan modelos y áreas; por eso describo sus patrones sin tratarlas como observaciones independientes en pruebas de significación.''')
r(34,'Explicar secuencia del estudio y prerregistro con vocabulario común.',r'''The work developed in stages. The initial structure and neighbour comparisons came before the expanded text experiment and the specialty searches. The geometric analysis was a later exploration, and the summary of 325 area pairs followed its first examples. Rules were recorded before the corresponding new calculations, with earlier results already known; some controls were added along the way. Supplement S2 documents this sequence. The full study was not registered in advance with an external service, so these later checks should not be read as predictions made before any results were seen.''',r'''El trabajo se desarrolló por etapas. Las primeras comparaciones de estructura y vecinos precedieron a la ampliación del experimento de texto y a las búsquedas por especialidad. El análisis geométrico fue una exploración posterior, y el resumen de las 325 parejas de áreas se hizo después de conocer sus primeros ejemplos. Las reglas se registraron antes de los nuevos cálculos correspondientes, con resultados anteriores ya conocidos; algunos controles se añadieron durante el proceso. El Suplemento S2 documenta esta secuencia. El estudio completo no se registró previamente en un servicio externo, por lo que estas comprobaciones posteriores no deben leerse como predicciones formuladas antes de ver ningún resultado.''')
r(35,'Empezar por el significado del acuerdo entre centros y explicar la media.',r'''Models share a similar arrangement of area centres, and choosing other papers changes that conclusion little. Each mean combines the 45 ways of pairing the ten models. For the original article selection, corrected CKA averages 0.939 for area centres and 0.911 for specialty centres. Across fifty selections, the averages are 0.940 and 0.911, with central 95\% selection ranges of 0.937--0.943 and 0.910--0.912 (Figure~\ref{fig:scales}A). Randomly redistributed groups average 0.627 and 0.636. None of their selection means reaches the lowest observed selection mean. Thus, the labelled groups produce more shared structure than these random references.''',r'''Los modelos comparten una organización parecida de los centros de áreas, y elegir otros artículos cambia poco esa conclusión. Cada media reúne las 45 formas de emparejar los diez modelos. En la selección original, la CKA corregida media es 0,939 para centros de áreas y 0,911 para centros de especialidades. Con cincuenta selecciones, las medias son 0,940 y 0,911, con rangos centrales del 95\% de 0,937--0,943 y 0,910--0,912 (Figura~\ref{fig:scales}A). Los grupos redistribuidos al azar dan medias de 0,627 y 0,636. Ninguna media de sus selecciones alcanza la menor media de las selecciones observadas. Por tanto, los grupos definidos por las etiquetas producen más estructura compartida que estas referencias aleatorias.''')
r(36,'Conectar tamaño, omisión y selección de especialidad con la misma conclusión.',r'''The arrangement also changes little when centres use more papers. At 128, 256 and 512 papers, area-centre means are 0.938, 0.940 and 0.941; the same 183 eligible specialties give 0.913, 0.914 and 0.915. Leaving out each area in turn gives 0.933--0.946 in the original comparison, so no single area accounts for the high agreement. When only one specialty represents each area, the mean is 0.904. In this restricted comparison, changing which specialty represents an area matters more than changing its selected papers (Table S18).''',r'''La organización también cambia poco cuando los centros utilizan más artículos. Con 128, 256 y 512 artículos, las medias de los centros de áreas son 0,938, 0,940 y 0,941; las mismas 183 especialidades con suficientes trabajos dan 0,913, 0,914 y 0,915. Retirar un área cada vez da valores entre 0,933 y 0,946 en la comparación original, por lo que ninguna explica por sí sola el alto acuerdo. Cuando una sola especialidad representa cada área, la media es 0,904. En esta comparación reducida, cambiar qué especialidad representa un área importa más que cambiar los artículos elegidos dentro de ella (Tabla S18).''')
fig(36,r'''Agreement about group centres and individual papers. Higher corrected CKA means greater agreement between models. (A) Each centre summarises 256 papers. Area and specialty results average fifty article selections. The 26-specialty condition chooses one specialty from each of the 26 areas, repeats that choice fifty times, and chooses ten article sets within each choice. Random groups redistribute the same papers, preserving sizes and dates. Lines span the central 95\% of selection means. (B) Agreement among individual papers within 26 areas and the same 183 specialties, at three article counts. Points show means; lines span the central 95\% of group--model-pair results: 1,170 for areas and 8,235 for specialties. Panel A compares relationships between group summaries; panel B compares relationships between papers inside groups. Their ranges describe different sources of variation and are not confidence intervals.''',r'''Acuerdo sobre centros de grupos y artículos individuales. Una CKA corregida mayor indica más acuerdo entre modelos. (A) Cada centro resume 256 artículos. Los resultados de áreas y especialidades promedian cincuenta selecciones de artículos. La condición de 26 especialidades elige una de cada una de las 26 áreas, repite esa elección cincuenta veces y elige diez conjuntos de artículos dentro de cada elección. Los grupos aleatorios redistribuyen los mismos artículos, conservando tamaños y fechas. Las líneas abarcan el 95\% central de las medias entre selecciones. (B) Acuerdo entre artículos individuales dentro de 26 áreas y las mismas 183 especialidades, con tres cantidades de artículos. Los puntos muestran medias; las líneas abarcan el 95\% central de los resultados de grupo y pareja de modelos: 1.170 para áreas y 8.235 para especialidades. El panel A compara relaciones entre resúmenes de grupos; el B, relaciones entre artículos dentro de grupos. Sus rangos describen fuentes distintas de variación y no son intervalos de confianza.''')
r(37,'Distinguir media estable, casos locales sensibles y objetos comparados.',r'''Agreement is lower when we compare the individual papers inside a group. Mean CKA stays around 0.63 within areas and 0.64 within the same 183 specialties as the count rises from 128 to 512 (Figure~\ref{fig:scales}B). That stable average hides individual comparisons that change more. Of the 8,235 combinations of a specialty and a model pair, 2,628 trigger the selection alert (31.9\%): their agreement changes more than the recorded tolerance allows across article choices or tested sizes. A stable mean therefore does not make every specialty result stable. The contrast with centres also concerns different objects---group summaries versus individual papers---so it does not isolate the effect of scale alone.''',r'''El acuerdo es menor cuando comparamos los artículos individuales dentro de un grupo. La CKA media se mantiene alrededor de 0,63 dentro de áreas y 0,64 dentro de las mismas 183 especialidades al pasar de 128 a 512 artículos (Figura~\ref{fig:scales}B). Esa media estable oculta comparaciones concretas que cambian más. De las 8.235 combinaciones de una especialidad y una pareja de modelos, 2.628 activan la alerta de selección (31,9\%): su acuerdo cambia más de lo permitido por la tolerancia registrada al elegir artículos o variar el tamaño entre los probados. Por tanto, una media estable no vuelve estable cada resultado de especialidad. La comparación con centros también utiliza objetos distintos: resúmenes de grupos frente a artículos individuales. No permite aislar el efecto de la escala por sí solo.''')
r(38,'Explicar correlación de rangos y denominador de otra alerta.',r'''The alternative structure measures broadly agree about which model pairs are more similar. Within each of the original 130 area--period groups, I order model pairs from less to more agreement and compare those orderings. Their mean rank correlations with corrected CKA are 0.891 for Procrustes and 0.881 for distance ranks; values nearer one mean more similar orderings. Agreement is not complete. The original article-selection check also retains 50 alerts among 5,850 comparisons, corresponding to 45 model pairs in each of the 130 groups (Table S4). This is a different check from the specialty alerts above, with its own sizes and tolerances.''',r'''Las medidas alternativas de estructura coinciden en buena parte sobre qué parejas de modelos se parecen más. Dentro de cada uno de los 130 grupos originales de área y período, ordeno las parejas de modelos de menor a mayor acuerdo y comparo esos órdenes. Sus correlaciones medias de rangos con la CKA corregida son 0,891 para Procrustes y 0,881 para el orden de distancias; los valores más cercanos a uno indican órdenes más parecidos. La coincidencia no es completa. La comprobación original de selección de artículos conserva además 50 alertas entre 5.850 comparaciones, correspondientes a 45 parejas de modelos en cada uno de los 130 grupos (Tabla S4). Es una comprobación distinta de las alertas de especialidades anteriores, con sus propios tamaños y tolerancias.''')
r(39,'Separar tres ámbitos de candidatos en orden y explicar cada porcentaje.',r'''When every paper in the same area and period is available as a candidate, two models share an average of 30.3\% of the 25 nearest neighbours: about eight papers out of 25. The average gives equal weight to each area--period group and model pair. Holding every group's candidate count at 2,048 gives 31.9\% agreement. The count is shared across groups; the actual papers are shared across models within each group, not across disciplines.

The general-collection search asks a broader question. It takes 100 starting papers from each of the 130 groups, giving 13,000 in total, and searches among the 400,000 general records. Agreement is 17.5\%. This search both admits other disciplines and periods and offers many more candidates. Because both change together, the comparison cannot tell us how much of the lower agreement comes from each change.''',r'''Cuando todos los artículos de una misma área y período están disponibles como candidatos, dos modelos comparten en promedio el 30,3\% de los 25 vecinos más próximos: unos ocho artículos de 25. La media da el mismo peso a cada grupo de área y período y a cada pareja de modelos. Fijar la cantidad de candidatos en 2.048 por grupo da un acuerdo del 31,9\%. La cantidad es común entre grupos; los artículos concretos son comunes entre modelos dentro de cada grupo, no entre disciplinas.

La búsqueda en la colección general plantea una pregunta más amplia. Toma 100 artículos de partida de cada uno de los 130 grupos, 13.000 en total, y busca entre los 400.000 registros generales. El acuerdo es del 17,5\%. Esta búsqueda admite otras disciplinas y períodos y, a la vez, ofrece muchos más candidatos. Como ambas cosas cambian juntas, la comparación no permite saber cuánto del menor acuerdo procede de cada cambio.''')
r(40,'Explicar el cambio de base 30,3 a 30,58 y la unidad de puntos porcentuales.',r'''Filtering source flags and duplicates changes little of this picture. To make the before-and-after comparison fair, both averages use only the starting papers that survive the filter. Their initial agreement is 30.58\%, slightly different from the 30.3\% for all starting papers above, and rises to 31.43\% after filtering candidates. The gain is 0.85 percentage points. Both averages still mean roughly eight shared papers out of 25. Keeping candidate counts fixed reduces the gain to 0.28 points with 1,024 candidates and 0.19 with 2,048. The issues removed by this filter explain little of the overall disagreement, although some areas change more than others (Table S19).''',r'''Filtrar las marcas de origen y los duplicados cambia poco este panorama. Para que la comparación de antes y después sea justa, ambas medias utilizan solo los artículos de partida que sobreviven al filtro. Su acuerdo inicial es del 30,58\%, algo distinto del 30,3\% anterior para todos los artículos de partida, y sube al 31,43\% tras filtrar los candidatos. La ganancia es de 0,85 puntos porcentuales. Ambas medias siguen equivalendo a unos ocho artículos compartidos de 25. Mantener fija la cantidad de candidatos reduce la ganancia a 0,28 puntos con 1.024 candidatos y 0,19 con 2.048. Los problemas eliminados por este filtro explican poco del desacuerdo general, aunque algunas áreas cambian más que otras (Tabla S19).''')
r(41,'Recordar qué se mantiene fijo antes de interpretar la búsqueda estrecha.',r'''The matched specialty searches isolate a change in disciplinary scope more closely: both searches have 256 candidates, the same starting papers and matched dates (Figure~\ref{fig:paired}). Searching within the specialty makes models share fewer of their 25 neighbours in 127 of 217 specialties (58.5\%), but more in the other 90 (41.5\%). The average change from the parent-area search is $-1.35$ percentage points. With lists of 50 neighbours, the split is almost even: 109 specialties decrease and 108 increase. Narrowing the search therefore does not have the same effect everywhere. These results describe how much the models' lists overlap; they do not assess how useful the listed papers are.''',r'''Las búsquedas emparejadas de especialidades permiten acotar mejor el cambio de alcance disciplinar: ambas tienen 256 candidatos, los mismos artículos de partida y fechas emparejadas (Figura~\ref{fig:paired}). Buscar dentro de la especialidad hace que los modelos compartan menos de sus 25 vecinos en 127 de 217 especialidades (58,5\%), pero más en las otras 90 (41,5\%). El cambio medio respecto a buscar en el área amplia es de $-1,35$ puntos porcentuales. Con listas de 50 vecinos, el reparto es casi igual: 109 especialidades bajan y 108 suben. Por tanto, estrechar la búsqueda no tiene el mismo efecto en todas partes. Estos resultados describen cuánto coinciden las listas de los modelos; no evalúan lo útiles que son los artículos encontrados.''')
fig(41,r'''Does searching within a specialty change agreement? Each point represents one of 217 specialties. The horizontal axis shows the fraction of neighbours shared by models when searching the parent area, such as Medicine. The vertical axis shows that fraction within its specialty, such as Cardiology and Cardiovascular Medicine. Above the diagonal, models share more neighbours in the narrower search; below it, they share fewer. Both candidate sets contain 256 papers, including the same 50 starting papers, with matched dates. Values average model pairs and ten choices of the other 206 candidates. The parent-area set always includes those 50 specialty papers. Differences between points describe specialties, not confidence intervals.''',r'''¿Cambia el acuerdo al buscar dentro de una especialidad? Cada punto representa una de 217 especialidades. El eje horizontal muestra la fracción de vecinos compartidos por los modelos al buscar en el área amplia, como Medicina. El vertical muestra esa fracción dentro de su especialidad, como Cardiología y Medicina Cardiovascular. Por encima de la diagonal, los modelos comparten más vecinos en la búsqueda estrecha; por debajo, menos. Ambos conjuntos tienen 256 candidatos, incluidos los mismos 50 artículos de partida, con fechas emparejadas. Los valores promedian parejas de modelos y diez elecciones de los otros 206 candidatos. El conjunto del área amplia siempre incluye esos 50 artículos de la especialidad. Las diferencias entre puntos describen especialidades, no intervalos de confianza.''')
r(42,'Dar interpretación a correlación y evitar confundir asociación con acuerdo alto.',r'''Pairs of models that agree more on overall structure also tend to share more neighbours. Ordering the 45 model pairs by each type of agreement gives a rank correlation of 0.920. This association does not make the two checks interchangeable: a pair can preserve broad relationships while replacing many individual neighbours. The model pairs also share models with one another, so the association is descriptive rather than evidence from 45 independent observations.''',r'''Las parejas de modelos que coinciden más en la estructura general también tienden a compartir más vecinos. Ordenar las 45 parejas de modelos según cada tipo de acuerdo da una correlación de rangos de 0,920. Esta asociación no vuelve intercambiables las dos comprobaciones: una pareja puede conservar las relaciones generales y sustituir muchos vecinos individuales. Además, las parejas reutilizan modelos, por lo que la asociación es descriptiva y no evidencia procedente de 45 observaciones independientes.''')
r(44,'Precisar conjunto candidato del experimento, cambio vs acuerdo y comparación modelo/texto.',r'''The input-text experiment now changes what the model reads. It uses the same 52,000 papers for three inputs: title alone, abstract alone, and title plus abstract. Here, each area contributes 2,000 candidates, combining its five periods. This differs from the preceding searches within a single area and period.

Starting from title plus abstract, I compare keeping the text and switching models with keeping the model and supplying only the title. The first replaces an average of 68.8\% of the 25 neighbours; the second replaces 70.7\% (Figure~\ref{fig:input}). These are fractions replaced, so a larger value means less agreement. The corresponding structural changes are 0.370 and 0.366, measured as one minus CKA: subtracting agreement from one makes larger values mean more change here too. The two average changes are similar, but they need not be similar for every model.''',r'''El experimento de texto cambia ahora lo que lee el modelo. Utiliza los mismos 52.000 artículos para tres entradas: solo título, solo resumen y título más resumen. Aquí, cada área aporta 2.000 candidatos que reúnen sus cinco períodos. Es una búsqueda distinta de las anteriores dentro de una sola área y período.

Partiendo de título más resumen, comparo mantener el texto y cambiar de modelo con mantener el modelo y darle solo el título. El primer cambio sustituye, en promedio, el 68,8\% de los 25 vecinos; el segundo, el 70,7\% (Figura~\ref{fig:input}). Son fracciones sustituidas, por lo que un valor mayor significa menos acuerdo. Los cambios de estructura correspondientes son 0,370 y 0,366, medidos como uno menos CKA: restar el acuerdo de uno hace que aquí también los valores mayores signifiquen más cambio. Los dos cambios medios se parecen, pero no tienen por qué parecerse en cada modelo.''')
fig(44,r'''Changing the model or changing its input. All comparisons use the same 52,000 papers, with 2,000 per area across five periods. The starting input is title plus abstract. Model change compares models on that input; text change keeps the model and uses only the title or only the abstract. Larger values mean more change: (A) one minus corrected CKA; (B) the fraction of 25 neighbours replaced among the area's 2,000 candidates. Each point is an area average. The line inside each box is the median; the box covers the middle half of area values. Whiskers extend to values within 1.5 box heights of the box edges. These distributions describe differences between areas, not confidence intervals. Models retain their usual text limits.''',r'''Cambiar de modelo o cambiar su entrada. Todas las comparaciones utilizan los mismos 52.000 artículos, con 2.000 por área repartidos entre cinco períodos. La entrada inicial es título más resumen. El cambio de modelo compara modelos con esa entrada; el cambio de texto mantiene el modelo y utiliza solo el título o solo el resumen. Los valores mayores indican más cambio: (A) uno menos CKA corregida; (B) fracción de 25 vecinos sustituidos entre los 2.000 candidatos del área. Cada punto es una media de área. La línea de cada caja es la mediana; la caja abarca la mitad central de los valores de áreas. Las líneas exteriores llegan hasta los valores situados a menos de 1,5 alturas de caja de sus bordes. Estas distribuciones describen diferencias entre áreas, no intervalos de confianza. Los modelos conservan sus límites habituales de texto.''')
r(45,'Recordar qué texto se conserva en abstract-only.',r'''Keeping the abstract and removing only the title changes less: 0.027 for structure and 22.1\% of neighbours. Titles alone also affect models differently, replacing 51.7\% of neighbours for MPNet and 84.2\% for SciBERT (Table S5). The similar overall averages therefore should not be read as a general equivalence between changing text and changing models.''',r'''Conservar el resumen y retirar solo el título cambia menos: 0,027 para estructura y el 22,1\% de los vecinos. Los títulos solos también afectan de forma distinta a cada modelo: sustituyen el 51,7\% de los vecinos de MPNet y el 84,2\% de los de SciBERT (Tabla S5). Por tanto, el parecido entre las medias generales no debe leerse como una equivalencia general entre cambiar el texto y cambiar de modelo.''')
r(46,'Explicar media muestra, nueva base de candidatos y signo de las diferencias.',r'''To see whether that average comparison repeats, I choose fifty balanced sets of 1,000 candidates per area, half the full experiment's count. These smaller searches replace 64.93\% of the 25 neighbours when switching models and 66.49\% with titles alone. Title-only input therefore replaces 1.56 percentage points more, with a central 95\% selection range of 1.44--1.69. The overall difference stays positive in every repetition. It averages 1.97 points with 10 neighbours and 1.04 with 50.

The model-specific results tell a less uniform story. Differences range from $-14.04$ points for MPNet to $+16.59$ for SciBERT. A negative value means that titles alone change fewer neighbours than switching models; a positive value means they change more. Thus, a repeatable positive grand mean combines models for which the two changes have opposite relative effects (Supplement S9).''',r'''Para ver si esa comparación media se repite, elijo cincuenta conjuntos equilibrados de 1.000 candidatos por área, la mitad de la cantidad del experimento completo. En estas búsquedas más pequeñas, cambiar de modelo sustituye el 64,93\% de los 25 vecinos y usar solo títulos, el 66,49\%. Los títulos solos sustituyen, por tanto, 1,56 puntos porcentuales más, con un rango central del 95\% entre selecciones de 1,44--1,69. La diferencia general se mantiene positiva en todas las repeticiones. Su media es de 1,97 puntos con 10 vecinos y 1,04 con 50.

Los resultados de cada modelo son menos uniformes. Las diferencias van de $-14,04$ puntos para MPNet a $+16,59$ para SciBERT. Un valor negativo significa que los títulos solos cambian menos vecinos que cambiar de modelo; uno positivo significa que cambian más. Así, una media general positiva que se repite reúne modelos en los que ambos cambios tienen efectos relativos opuestos (Suplemento S9).''')
r(47,'Explicar reversión al cambiar pooling y alcance práctico de la comparación.',r'''Changing the rule that forms a paper vector can also reverse the overall result. For the four word-level models---BERT, SciBERT, BioBERT and PubMedBERT---I replace the mean of token outputs with the CLS or SEP output defined above. The other six models keep their usual rules. Both sides of the comparison are recalculated: the effect of switching models and the effect of supplying titles alone. With 25 neighbours, titles alone now replace 3.13 percentage points fewer for CLS and 2.00 fewer for SEP, in every repetition. The ordering therefore depends on this processing choice. These are comparisons of practical ways to use the models; they do not isolate the causal contribution of text, model design or a single processing step.''',r'''Cambiar la regla que forma el vector del artículo también puede invertir el resultado general. Para los cuatro modelos de palabras ---BERT, SciBERT, BioBERT y PubMedBERT--- sustituyo la media de las salidas de tokens por la salida CLS o SEP definida antes. Los otros seis mantienen sus reglas habituales. Se vuelven a calcular los dos lados de la comparación: el efecto de cambiar de modelo y el de dar solo títulos. Con 25 vecinos, los títulos solos sustituyen ahora 3,13 puntos porcentuales menos con CLS y 2,00 menos con SEP, en todas las repeticiones. El orden depende, por tanto, de esta decisión de procesamiento. Son comparaciones de formas prácticas de usar los modelos; no aíslan la contribución causal del texto, del diseño del modelo o de un único paso de procesamiento.''')
r(48,'Dar sentido a ampliación 26k/52k y separar controles de longitud.',r'''The expansion from the first 26,000 papers to 52,000 also reduced sensitivity to article selection in the structural comparison. Applying the same check with 100 repeated selections at each size lowers alerts from 72 of 520 model--area--input contrasts (13.8\%) to five of 520 (1.0\%). Fewer contrasts therefore exceed the recorded tolerance. This does not establish stability for every neighbour comparison. Supplement S3 retains the earlier twenty-selection check separately. The common-passage and MiniLM 512-token checks instead concern input length; they do not reveal a coding error in MiniLM's original limit.''',r'''La ampliación de los primeros 26.000 artículos a 52.000 también redujo la sensibilidad a la selección en la comparación de estructura. Aplicar la misma comprobación con 100 selecciones repetidas en cada tamaño reduce las alertas de 72 entre 520 contrastes de modelo, área y entrada (13,8\%) a cinco entre 520 (1,0\%). Menos contrastes superan, por tanto, la tolerancia registrada. Esto no demuestra estabilidad para cada comparación de vecinos. El Suplemento S3 conserva por separado la comprobación anterior de veinte selecciones. Las pruebas de fragmento común y de MiniLM con 512 tokens tratan, en cambio, sobre la longitud de entrada; no revelan un error de programación en el límite original de MiniLM.''')
r(49,'Volver a plantear la pregunta geométrica y separar los dos controles de estabilidad.',r'''The final analysis asks whether models support the same description of an area. It reuses the input-text experiment's 52,000 papers and their title-plus-abstract vectors. For example, do the arrows representing one area's papers point further apart than those of another? Before comparing areas, I check whether each area's measured value changes greatly when other papers are chosen.

Ten models and 26 areas give 260 cases to check. Angular spread has no selection alerts in either the half-sample or equal-size check. PR has four alerts (1.5\%) with twenty half samples of 1,000 papers per area, and none with five further selections of 2,000. These checks use different sizes and repetition counts. Passing the second does not remove the sensitivity detected by the first.''',r'''El último análisis pregunta si los modelos respaldan la misma descripción de un área. Reutiliza los 52.000 artículos del experimento de texto y sus vectores de título más resumen. Por ejemplo, ¿apuntan más separadas las flechas que representan los artículos de un área que las de otra? Antes de comparar áreas, compruebo si el valor medido en cada una cambia mucho al elegir otros artículos.

Diez modelos y 26 áreas dan 260 casos que comprobar. La apertura angular no tiene alertas de selección ni en la prueba de medias muestras ni en la de igual tamaño. PR tiene cuatro alertas (1,5\%) con veinte medias muestras de 1.000 artículos por área y ninguna con cinco selecciones adicionales de 2.000. Estas pruebas utilizan tamaños y cantidades de repeticiones distintos. Pasar la segunda no elimina la sensibilidad detectada por la primera.''')
r(50,'Aclarar quién discrepa sobre qué, con un ejemplo independiente de tecnicismos.',r'''Repeatable values within a model do not ensure agreement between models. Among the 325 area pairs, 80.6\% have persistent opposite answers from at least two models for angular spread, and 68.0\% for PR (Figure~\ref{fig:pairs}). For example, one fixed model gives area A a larger angular spread than B in every article selection, while another gives B the larger spread in every selection. The other models need not all disagree with one another. ``Larger'' refers to the measured property, not to a higher position in a drawing or better research.

Unanimous agreement is less common: all ten models persistently give the same area the larger value in 12.9\% of pairs for angular spread and 16.6\% for PR. The remaining 6.5\% and 15.4\% do not meet either the unanimous-agreement or opposition rule. They remain unresolved under those rules.''',r'''Que los valores se repitan dentro de un modelo no garantiza el acuerdo entre modelos. Entre las 325 parejas de áreas, el 80,6\% tiene respuestas opuestas persistentes de al menos dos modelos para apertura angular, y el 68,0\% para PR (Figura~\ref{fig:pairs}). Por ejemplo, un modelo concreto da al área A mayor apertura angular que a B en todas las selecciones de artículos, mientras otro da mayor apertura a B en todas ellas. No hace falta que los demás modelos discrepen todos entre sí. Mayor se refiere a la propiedad medida, no a una posición más alta en un dibujo ni a mejor investigación.

El acuerdo unánime es menos frecuente: los diez modelos dan de forma persistente el valor mayor a la misma área en el 12,9\% de las parejas para apertura angular y el 16,6\% para PR. El 6,5\% y el 15,4\% restantes no cumplen ni la regla de acuerdo unánime ni la de oposición. Quedan sin resolver con esas reglas.''')
r(51,'Distinguir porcentaje de diferencia y porcentaje de parejas.',r'''Many reversals concern small differences between areas. Requiring each persistent ordering to exceed a 5\% difference, relative to the two measured values' average, reduces opposition to 29.5\% of the 325 pairs for angular spread and 54.5\% for PR. At a 10\% minimum difference, the shares fall to 5.8\% and 38.8\%. The first percentage in each comparison is a requirement on the difference's size; the resulting percentage tells us how many pairs still meet it. A reversal over a tiny difference and one over a larger difference should not carry the same interpretation.''',r'''Muchas inversiones corresponden a diferencias pequeñas entre áreas. Exigir que cada orden persistente supere una diferencia del 5\%, respecto al promedio de los dos valores medidos, reduce la oposición al 29,5\% de las 325 parejas para apertura angular y al 54,5\% para PR. Con una diferencia mínima del 10\%, las proporciones bajan al 5,8\% y al 38,8\%. El primer porcentaje de cada comparación es una exigencia sobre el tamaño de la diferencia; el porcentaje resultante indica cuántas parejas siguen cumpliéndola. Una inversión con una diferencia mínima y otra con una diferencia mayor no deberían interpretarse igual.''')
fig(51,r'''How model agreement changes with the representation. Each bar covers all 325 pairs of areas. Blue: all ten models persistently give the same area the larger measured value. Orange: at least two fixed models persistently give opposite orderings. Grey: neither rule is met. Every ordering must hold across 26 conditions: the main 2,000 papers per area, twenty half samples of 1,000, and five further selections of 2,000. Original and centred representations use the same papers. Centring moves the origin to each model's mean over the balanced 52,000 unit vectors, then rescales the resulting vectors to length one. A cutoff of 5\% requires a difference greater than 5\% of the two area values' average in every condition; the 0 cutoff requires a nonzero difference. Table S20 reports all four cutoffs and whether the same models retain the same opposing area orderings.''',r'''Cómo cambia el acuerdo entre modelos al cambiar la representación. Cada barra abarca las 325 parejas de áreas. Azul: los diez modelos dan de forma persistente el valor mayor a la misma área. Naranja: al menos dos modelos concretos mantienen órdenes opuestos. Gris: no se cumple ninguna de las dos reglas. Cada orden debe mantenerse en 26 condiciones: los 2.000 artículos principales por área, veinte medias muestras de 1.000 y cinco selecciones adicionales de 2.000. Las representaciones original y centrada usan los mismos artículos. El centrado lleva el origen a la media de los 52.000 vectores de longitud uno, equilibrados por área y período, de cada modelo; después reajusta los vectores resultantes a longitud uno. El corte del 5\% exige una diferencia mayor que el 5\% del promedio de los dos valores de áreas en todas las condiciones; el corte 0 exige una diferencia distinta de cero. La Tabla S20 recoge los cuatro cortes y si los mismos modelos conservan los mismos órdenes opuestos entre áreas.''')
r(52,'Desarrollar retención y evitar que un empate implique que toda pareja quede sin resolver.',r'''The alternative formulas often retain the disagreement, but not in every case. I count an opposition as retained only when at least one of the original opposing model pairs keeps the same area orderings. Alternative angle summaries retain 85.9\% of the original angular oppositions by this rule (225/262). Across the same 26 article conditions, entropy-based dimension retains 94.6\% of the original PR oppositions and D80 retains 86.0\%; 86.0\% survive both alternatives (190/221). These denominators are the original opposed pairs, not all area pairs. Because D80 returns whole numbers, it can give ties that contribute no persistent ordering.

The four word-level models do not account for all opposition either. Keeping only the six models trained for similarity still leaves opposite answers in 71.1\% of all 325 pairs for angular spread and 49.2\% for PR (Tables S14--S15).''',r'''Las fórmulas alternativas suelen conservar el desacuerdo, aunque no en todos los casos. Solo cuento una oposición como conservada si al menos una de las parejas de modelos originalmente opuestos mantiene los mismos órdenes entre áreas. Las medidas angulares alternativas conservan con esta regla el 85,9\% de las oposiciones angulares originales (225/262). En las mismas 26 condiciones de artículos, la dimensión por entropía conserva el 94,6\% de las oposiciones originales de PR y D80, el 86,0\%; el 86,0\% se mantiene con ambas alternativas (190/221). Estos denominadores son las parejas originalmente opuestas, no todas las parejas de áreas. Como D80 devuelve números enteros, puede dar empates que no aportan un orden persistente.

Los cuatro modelos de palabras tampoco explican toda la oposición. Conservar solo los seis modelos entrenados para similitud sigue dejando respuestas contrarias en el 71,1\% de las 325 parejas para apertura angular y el 49,2\% para PR (Tablas S14--S15).''')
r(53,'Explicar efecto del origen y separar total de oposiciones de continuidad de las originales.',r'''Angular comparisons change much more when the common reference point moves to the mean position of the balanced 52,000 papers (Figure~\ref{fig:pairs}). After subtracting that mean and restoring unit vector length, opposition falls from 80.6\% to 46.5\% of all 325 pairs: from 262 to 151. But the new total does not tell us which original disagreements remain. Only 48.9\% of the original oppositions retain at least one of the same opposing model pairs with the same area orderings (128/262). Table S20 separates these from new oppositions or those supported by different model pairs. With the 5\% minimum-difference rule, only 11 opposed pairs remain instead of 96.

PR is less sensitive to this transformation. Opposed pairs fall from 221 to 211, and 92.3\% of the original oppositions retain at least one of the same opposing model pairs and area orderings (204/221). An angular comparison that repeats with other papers can therefore still depend strongly on the origin from which angles are measured.''',r'''Las comparaciones angulares cambian mucho más al mover el punto común de referencia a la posición media de los 52.000 artículos equilibrados (Figura~\ref{fig:pairs}). Después de restar esa media y reajustar la longitud de los vectores a uno, la oposición baja del 80,6\% al 46,5\% de las 325 parejas: de 262 a 151. Pero el nuevo total no dice qué desacuerdos originales permanecen. Solo el 48,9\% de las oposiciones originales conserva al menos una de las mismas parejas de modelos opuestos con los mismos órdenes entre áreas (128/262). La Tabla S20 separa estas de las oposiciones nuevas o respaldadas por otras parejas de modelos. Con la regla de diferencia mínima del 5\%, quedan solo 11 parejas opuestas en vez de 96.

PR es menos sensible a esta transformación. Las parejas opuestas bajan de 221 a 211, y el 92,3\% de las oposiciones originales conserva al menos una de las mismas parejas de modelos opuestos y los mismos órdenes entre áreas (204/221). Por tanto, una comparación angular que se repite con otros artículos puede seguir dependiendo mucho del origen desde el que medimos los ángulos.''')
r(54,'Relacionar la comprobación fallida con la interpretación que no sostiene.',r'''The attempt to identify separate groups from links between nearby papers reached a different limit. Weak connections might seem to suggest an area divided into research topics. Yet artificial elongated clouds and isolated extreme points produce that signal without any thematic groups. It also changes with sample size and the rule for linking neighbours, with selection alerts in 51 of 260 cases. Supplement S6 retains this unsuccessful check because it shows a problem that repeatability alone cannot solve: a geometric signal may not describe the feature of research we want to study.''',r'''El intento de identificar grupos separados mediante enlaces entre artículos cercanos llegó a otro límite. Unas conexiones débiles podrían parecer señal de un área dividida en temas de investigación. Sin embargo, las nubes artificiales alargadas y los puntos extremos aislados producen esa señal sin que haya grupos temáticos. Además, cambia con el tamaño de muestra y con la regla que enlaza vecinos, con alertas de selección en 51 de 260 casos. El Suplemento S6 conserva esta comprobación fallida porque muestra un problema que la repetición, por sí sola, no resuelve: una señal geométrica puede no describir la característica de la investigación que queremos estudiar.''')
r(55,'Hacer explícita la consecuencia de estabilidad frente a desacuerdo.',r'''A high overall agreement score leaves some practical questions open. The models can share the broad arrangement of areas while directing a reader towards different papers or giving opposite comparisons between areas. Suppose one model gives area A a larger angular spread than B, and the result repeats with other articles. That shows stability to article selection within this model. If another model persistently reverses the order, more selections with the first model do not resolve the disagreement. The claim needs to be checked by changing the model as well as the articles.''',r'''Una puntuación general de acuerdo alta deja abiertas algunas preguntas prácticas. Los modelos pueden compartir la organización amplia de las áreas y, a la vez, llevar al lector hacia artículos distintos o dar comparaciones opuestas entre áreas. Supongamos que un modelo da al área A mayor apertura angular que a B y el resultado se repite con otros artículos. Eso muestra estabilidad ante la selección dentro de ese modelo. Si otro modelo invierte el orden de forma persistente, hacer más selecciones con el primero no resuelve el desacuerdo. La afirmación necesita comprobarse cambiando también de modelo, además de artículos.''')
r(57,'Recordar qué significan las propiedades sin introducir nuevas equivalencias temáticas.',r'''Interpretation also depends on what the measure describes. Larger angles mean that vectors point further apart; a larger effective linear dimension means that their variation is less concentrated in a few directions. Those are descriptions of the representation. Calling an area more thematically diverse or interdisciplinary would require a further link between those numerical properties and the research itself. Related work on embedding geometry cautions against assigning a broad meaning to a convenient measure \citep{rudman-etal-2022-isoscore}. The failed fragmentation check illustrates why: even a geometric difference that repeats can support the wrong explanation.''',r'''La interpretación también depende de lo que describe la medida. Unos ángulos mayores indican que los vectores apuntan más separados; una dimensión lineal efectiva mayor indica que su variación está menos concentrada en unas pocas direcciones. Son descripciones de la representación. Llamar a un área más diversa en temas o más interdisciplinar exigiría establecer otra relación entre esas propiedades numéricas y la investigación. Otros trabajos sobre geometría de embeddings advierten del riesgo de atribuir un significado amplio a una medida cómoda \citep{rudman-etal-2022-isoscore}. La comprobación fallida de fragmentación muestra por qué: incluso una diferencia geométrica que se repite puede sostener una explicación equivocada.''')
r(58,'Recuperar hallazgos y su límite sin listar pruebas sin propósito.',r'''The additional checks narrow the explanations for the main findings. The shared arrangement of area centres is not tied to one set of papers, to choosing 128 rather than 256 or 512, or to including one particular area. The low neighbour overlap is also not largely removed by the recorded quality filter: after excluding flagged and duplicate records, two models still share about eight papers in a list of 25. These checks strengthen those observations within the tested collection, without establishing the accuracy of the shared relationships.''',r'''Las comprobaciones adicionales acotan las explicaciones de los resultados principales. La organización compartida de los centros de áreas no depende de un único conjunto de artículos, de elegir 128 en vez de 256 o 512, ni de incluir un área concreta. El filtro de calidad registrado tampoco elimina la mayor parte del bajo acuerdo entre vecinos: tras excluir registros marcados y duplicados, dos modelos siguen compartiendo unos ocho artículos en una lista de 25. Estas pruebas refuerzan esas observaciones dentro de la colección estudiada, sin establecer que las relaciones compartidas sean correctas.''')
r(59,'Explicar la consecuencia de modelos y pooling sin nombres nuevos.',r'''For input text, the repeated selections preserve an average result that hides different model behaviours. Giving titles alone changes fewer neighbours than switching models for some models, and more for others. Replacing mean pooling with the first or last contextual output in the four word-level models also reverses the overall ordering. The practical consequence is to specify both what text a model reads and how its outputs become a paper vector. A statement that text and model choice matter equally would go beyond these results.''',r'''En el experimento de texto, las selecciones repetidas conservan un resultado medio que oculta comportamientos distintos. Dar solo títulos cambia menos vecinos que cambiar de modelo en unos modelos, y más en otros. Sustituir la media por la primera o la última salida que ha procesado el contexto, en los cuatro modelos de palabras, también invierte el orden general. La consecuencia práctica es indicar tanto qué texto lee el modelo como la regla que convierte sus salidas en un vector por artículo. Afirmar que el texto y el modelo importan por igual iría más allá de estos resultados.''')
r(60,'Recuperar origen y normalización como decisión concreta.',r'''For angular spread, the common reference point is another consequential choice. Moving it to the mean of the balanced article set and rescaling the vectors changes many answers about which area has the larger spread. Repeating article selection does not remove this dependence or establish one representation as correct. PR changes less, although alternative dimension formulas still fail to retain every comparison. A claim about spread therefore needs to identify the representation, the measure and the size of the difference.''',r'''Para la apertura angular, el punto común de referencia es otra decisión relevante. Moverlo a la media del conjunto equilibrado de artículos y reajustar los vectores cambia muchas respuestas sobre qué área tiene mayor dispersión. Repetir la selección de artículos no elimina esa dependencia ni establece que una representación sea la correcta. PR cambia menos, aunque las fórmulas alternativas de dimensión tampoco conservan todas las comparaciones. Por eso, una afirmación sobre dispersión debe identificar la representación, la medida y el tamaño de la diferencia.''')
r(61,'Explicar composición, familias y por qué el contraste no aísla causas.',r'''The discipline checks examine one concrete difference: models agree less about the relationships among Medicine papers than among Energy papers under the main rule (Supplement S5). This does not mean that Medicine is less coherent, and it does not always have the lowest neighbour overlap. The structural difference remains when the contributions of specialties within each area are balanced, and when the two biomedical models, BioBERT and PubMedBERT, are excluded. Neither tested explanation accounts for the whole difference. Models with related training also sometimes give similar results, but these apparent families change with the rule used to form paper vectors. With ten models that differ simultaneously in training texts, internal design and the task used to train them, these associations cannot identify one of those features as the cause.''',r'''Las comprobaciones por disciplina examinan una diferencia concreta: con la regla principal, los modelos coinciden menos sobre las relaciones entre artículos de Medicina que entre artículos de Energía (Suplemento S5). Esto no significa que Medicina sea menos coherente, y tampoco tiene siempre el menor acuerdo de vecinos. La diferencia de estructura persiste al equilibrar la contribución de las especialidades dentro de cada área y al excluir los dos modelos biomédicos, BioBERT y PubMedBERT. Ninguna de las dos explicaciones probadas da cuenta de toda la diferencia. Los modelos con entrenamientos relacionados también producen a veces resultados parecidos, pero esas aparentes familias cambian con la regla que forma los vectores. Con diez modelos que difieren a la vez en los textos de entrenamiento, el diseño interno y la tarea para la que se entrenaron, estas asociaciones no permiten identificar una de esas características como la causa.''')
r(62,'Explicar que cambia la fecha de los artículos, no la antigüedad del modelo.',r'''The time comparison applies the same current models to papers from older and newer publication periods. Structural agreement increases slightly on average. Neighbour agreement falls by 0.87 percentage points when each group offers all its available papers, but rises by 0.91 points when every group offers 2,048 candidates. The apparent trend therefore depends on whether older and newer groups are allowed different search sizes. It describes agreement among present-day representations of those papers; it does not, by itself, show that science has historically converged.''',r'''La comparación temporal aplica los mismos modelos actuales a artículos de períodos de publicación antiguos y recientes. El acuerdo de estructura aumenta ligeramente en promedio. El acuerdo de vecinos baja 0,87 puntos porcentuales cuando cada grupo ofrece todos sus artículos disponibles, pero sube 0,91 puntos cuando todos ofrecen 2.048 candidatos. Por tanto, la tendencia aparente depende de si permitimos tamaños de búsqueda distintos entre los grupos antiguos y recientes. Describe el acuerdo entre representaciones actuales de esos artículos; por sí sola, no muestra que la ciencia haya convergido históricamente.''')
r(64,'Evitar encoder y dirección como sinónimos no explicados.',r'''The ten models also set a boundary. Four were not trained specifically for document similarity. The six-model check shows that disagreement is not confined to those four, but does not make this set representative of all embedding models. To decide which area ordering or article relationship is better supported, we need evidence outside these vectors, such as independent assessments of the papers.''',r'''Los diez modelos también fijan un límite. Cuatro no se entrenaron específicamente para comparar documentos. La prueba con seis muestra que el desacuerdo no se limita a esos cuatro, pero no hace que este conjunto represente todos los modelos de embeddings. Para decidir qué orden entre áreas o qué relación entre artículos tiene mejor respaldo, necesitamos evidencia externa a estos vectores, como evaluaciones independientes de los trabajos.''')
r(65,'Explicar confirmatorio y siguiente paso en lenguaje común.',r'''Several extensions and controls also followed earlier results. Recording their rules before the new calculations makes the decisions traceable, but does not turn them into predictions made before the study began. A useful next step would test a specific map-based claim against independent judgments in a research area. Adding models alone would not settle what their shared or conflicting geometry means.''',r'''Varias ampliaciones y controles también se hicieron después de conocer resultados anteriores. Registrar sus reglas antes de los nuevos cálculos permite seguir las decisiones, pero no las convierte en predicciones formuladas antes de empezar el estudio. Un siguiente paso útil sería contrastar una afirmación concreta extraída del mapa con juicios independientes en un área de investigación. Añadir modelos, por sí solo, no resolvería qué significa su geometría compartida o contradictoria.''')
r(66,'Cerrar con la afirmación concreta que necesita revisión, manteniendo la voz.',r'''Changing the embedding model can preserve the broad arrangement of science while changing which papers appear nearby and which area has more widely spread representations. Giving a model titles alone can also produce large changes, with effects that depend on the model and the rule used to form paper vectors. Choosing other articles tests one source of dependence; changing models or the reference point tests others. Before using a map to support a particular relationship, we should check that relationship under the choices that can affect it and show how large the changes are. The tested models' agreement tells us what their representations share. Deciding whether that relationship describes the research well still needs independent evidence.''',r'''Cambiar el modelo de embeddings puede conservar la organización general de la ciencia y cambiar qué artículos aparecen cerca y qué área tiene representaciones más dispersas. Dar al modelo solo títulos también puede producir cambios grandes, con efectos que dependen del modelo y de la regla que forma el vector del artículo. Elegir otros artículos comprueba una fuente de dependencia; cambiar de modelo o de punto de referencia comprueba otras. Antes de usar un mapa para sostener una relación concreta, conviene comprobar esa relación con las decisiones que pueden afectarla y mostrar cuánto cambia. El acuerdo entre los modelos probados indica qué comparten sus representaciones. Decidir si esa relación describe bien la investigación sigue necesitando evidencia independiente.''')
# The main CKA subsection now concerns shared structure only; spread has its own entry.
for lang,old,new in [('en','Measuring shared structure and spread within an area','Measuring shared structure'),('es','Cómo se mide la estructura compartida y la dispersión de un área','Cómo se mide la estructura compartida')]:
 blocks[lang][28]=blocks[lang][28].replace(old,new)
# Keep the three research questions together and avoid an almost empty forced page.
for lang in folders:
 blocks[lang][12]=r'\Needspace{16\baselineskip}'+'\n'+blocks[lang][12]
 blocks[lang][16]=blocks[lang][16].replace('\\clearpage\n','')
changes.append({'block':12,'reason':'Mantener juntas las tres preguntas en la maqueta.'})

# Use standard LaTeX inverted punctuation, consistently with the existing source.
for lang,folder in folders.items():
 if lang=='es':blocks[lang]=[b.replace('¿',r'\textquestiondown{}') for b in blocks[lang]]
 text='\n\n'.join(blocks[lang]);(ROOT/folder/'main.tex').write_text(text)
report=[]
for i in range(len(base['en'])):
 report.append({'block':i,'reviewed':True,'changed':any(base[k][i]!=blocks[k][i] for k in folders),
  'reason':next((c['reason'] for c in changes if c['block']==i),'Conservado tras releer: lenguaje, contexto y alcance adecuados.'),
  'before':{k:base[k][i] for k in folders},'after':{k:blocks[k][i] for k in folders}})
(HERE/'paragraph_review.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n')
print(f'Reviewed {len(report)} aligned blocks; revised {sum(x["changed"] for x in report)} in both languages.')
